        Reverse("1\u200c2\u200d3\u200e4\u200f5", listOf("5\u200f4\u200e3\u200d2\u200c1", "5\u200f4\u200e3\u200d2\u200c1", "5\u200f4\u200e3\u200d2\u200c1", "5\u200f4\u200e3\u200d2\u200c1", "5\u200f4\u200e3\u200d2\u200c1", "54321", "54321", "5\u200f4\u200e3\u200d2\u200c1", "5\u200f4\u200e3\u200d2\u200c1", "5\u200f4\u200e3\u200d2\u200c1", "54321")),
        Reverse("\ud83d\ude00(\ud834\udd1e)\ud83b\ude00", listOf("\ud83b\ude00)\ud834\udd1e(\ud83d\ude00", "\ud83b\ude00)\ud834\udd1e(\ud83d\ude00", "\ud83b\ude00(\ud834\udd1e)\ud83d\ude00", "\ud83b\ude00(\ud834\udd1e)\ud83d\ude00", "\ud83b\ude00)\ud834\udd1e(\ud83d\ude00", "\ud83b\ude00)\ud834\udd1e(\ud83d\ude00", "\ud83b\ude00(\ud834\udd1e)\ud83d\ude00", "\ud83b\ude00)\ud834\udd1e(\ud83d\ude00", "\ud83b\ude00(\ud834\udd1e)\ud83d\ude00", "\ud83b\ude00)\ud834\udd1e(\ud83d\ude00", "\ud83b\ude00(\ud834\udd1e)\ud83d\ude00")),
