    )
    private fun input(case: Case) = object : BidiWriterInput {
        override val text = case.text.toCharArray()
        override val length = case.length
        override val reorderingOptions = case.reorder
        override val reorderingMode = case.mode
        override val dirProps = case.props
        override fun countRuns(): Int = case.runs.size
        override fun getVisualRun(index: Int): BidiRun = case.runs[index].let { BidiRun(it[0], it[1], it[2].toByte()) }
        override fun getInsertRemove(index: Int): Int = case.runs[index][3]
        override fun isInverse(): Boolean = case.inverse
        override fun testDirPropFlagAt(flag: Int, index: Int): Boolean = ((1 shl bidiByteAt(dirProps, index).toInt()) and flag) != 0
    }
    @Test fun sourceResolvedRunsAllModesMarksControlsAndReversedOutput() {
        assertEquals(49, cases.size)
        for ((index, case) in cases.withIndex()) for ((i, flags) in options.withIndex()) {
            val actual = try { "ok:" + BidiWriterCore.writeReordered(input(case), flags) }
                catch (_: IndexOutOfBoundsException) { "<bounds>" }
            assertEquals(case.expected[i], actual, "case $index / ${case.mode}/${case.reorder}/$flags")
        }
    }
    @Test fun reverseSourceGoldensCombiningMirrorsSupplementaryAndMalformedUtf16() {
        for (case in reverses) for ((i, flags) in options.withIndex())
            assertEquals(case.expected[i], BidiWriterCore.reverse(case.text, flags), "${case.text}/$flags")
        assertFailsWith<IllegalArgumentException> { BidiWriterCore.reverse(null, 0) }
    }
    @Test fun emptyProcessedParagraphReturnsBeforeWriterCallbacks() {
        val input = object : BidiWriterInput {
            override val length = 0
            override val text: CharArray get() = error("text read")
            override val dirProps: ByteArray? get() = error("props read")
            override val reorderingMode: Int get() = error("mode read")
            override val reorderingOptions: Int get() = error("options read")
            override fun countRuns(): Int = error("runs read")
            override fun getVisualRun(index: Int): BidiRun = error("run read")
            override fun getInsertRemove(index: Int): Int = error("marks read")
            override fun isInverse(): Boolean = error("inverse read")
            override fun testDirPropFlagAt(flag: Int, index: Int): Boolean = error("props read")
        }
        assertEquals("", BidiWriterCore.writeReordered(input, 31))
    }

